void FbTFT::scl300_write_reg_multi_byte( const uint8_t *buf, uint16_t len)
{

    int i;

    unsigned char * tx_buffer = (unsigned char *)malloc(len+2);



    for (i = 0; i < len; i++)
    {
        tx_buffer[i] = buf[i];
    }

   // CS(0);
    #ifdef Q_OS_LINUX
    struct spi_ioc_transfer transfer;

    memset(&transfer,0,sizeof(struct spi_ioc_transfer));

    transfer.tx_buf = (unsigned long)tx_buffer;
    transfer.len = len;

    int ret = ioctl(devfd, SPI_IOC_MESSAGE(1), &transfer);


    if (ret < 1)
    {
        perror("ioctl()");
        fprintf(stderr,"ioctl returned %d\n",ret);
    }



    #endif

    //CS(1);
    free(tx_buffer);
}
void FbTFT::LCD_Writ_Bus(uint8_t dat)
{
    uint8_t data1[1]={0};
    data1[0]=dat;
    //SPI1_read_write_byte(dat);
    scl300_write_reg_multi_byte( data1, 1);
}
void FbTFT::LCD_WR_DATA8(uint8_t dat)
{
    LCD_Writ_Bus(dat);
}
void FbTFT::LCD_WR_DATA(uint8_t dat)
{


    uint8_t data1[1]={0};
    data1[0]=dat;

    scl300_write_reg_multi_byte( data1, 1);
}
void FbTFT::LCD_WR_REG(uint8_t dat)
{


    uint8_t data1[1]={0};
    data1[0]=dat;
    LCD_DC_Clr();
    scl300_write_reg_multi_byte( data1, 1);
    LCD_DC_Set();


   // LCD_DC_Clr();
   // LCD_Writ_Bus(dat);
   // LCD_DC_Set();
}

/*****************************************************************************
 * @name       :void LCD_WriteReg(u8 LCD_Reg, u16 LCD_RegValue)
 * @date       :2018-08-09
 * @function   :Write data into registers
 * @parameters :LCD_Reg:Register address
                LCD_RegValue:Data to be written
 * @retvalue   :None
******************************************************************************/
void FbTFT::LCD_WriteReg(uint8_t LCD_Reg, uint16_t LCD_RegValue)
{
    LCD_WR_REG(LCD_Reg);
    LCD_WR_DATA(LCD_RegValue);
}
/*****************************************************************************
 * @name       :void LCD_WriteRAM_Prepare(void)
 * @date       :2018-08-09
 * @function   :Write GRAM
 * @parameters :None
 * @retvalue   :None
******************************************************************************/
void FbTFT::LCD_WriteRAM_Prepare(void)
{
    LCD_WR_REG(lcddev.wramcmd);
}
/*****************************************************************************
 * @name       :void Lcd_WriteData_16Bit(u16 Data)
 * @date       :2018-08-09
 * @function   :Write an 16-bit command to the LCD screen
 * @parameters :Data:Data to be written
 * @retvalue   :None
******************************************************************************/
void FbTFT::Lcd_WriteData_16Bit(uint16_t Data)
{
  //18Bit
//    LCD_WR_DATA((Data>>8)&0xF8);//RED
//    LCD_WR_DATA((Data>>3)&0xFC);//GREEN
//    LCD_WR_DATA(Data<<3);//BLUE




    int len=3;
    unsigned char * tx_buffer = (unsigned char *)malloc(len+2);




    tx_buffer[0] =(Data>>8)&0xF8;
    tx_buffer[1] =(Data>>3)&0xFC;
    tx_buffer[2] =Data<<3;


   // CS(0);
    #ifdef Q_OS_LINUX
    struct spi_ioc_transfer transfer;

    memset(&transfer,0,sizeof(struct spi_ioc_transfer));

    transfer.tx_buf = (unsigned long)tx_buffer;
    transfer.len = len;

    int ret = ioctl(devfd, SPI_IOC_MESSAGE(1), &transfer);


    if (ret < 1)
    {
        perror("ioctl()");
        fprintf(stderr,"ioctl returned %d\n",ret);
    }



    #endif

    //CS(1);
    free(tx_buffer);
}

/*****************************************************************************
 * @name       :void LCD_SetWindows(u16 xStar, u16 yStar,u16 xEnd,u16 yEnd)
 * @date       :2018-08-09
 * @function   :Setting LCD display window
 * @parameters :xStar:the bebinning x coordinate of the LCD display window
                                yStar:the bebinning y coordinate of the LCD display window
                                xEnd:the endning x coordinate of the LCD display window
                                yEnd:the endning y coordinate of the LCD display window
 * @retvalue   :None
******************************************************************************/
void FbTFT::LCD_SetWindows(uint16_t xStar, uint16_t yStar,uint16_t xEnd,uint16_t yEnd)
{
    LCD_WR_REG(lcddev.setxcmd);
    LCD_WR_DATA(xStar>>8);
    LCD_WR_DATA(0x00FF&xStar);
    LCD_WR_DATA(xEnd>>8);
    LCD_WR_DATA(0x00FF&xEnd);

    LCD_WR_REG(lcddev.setycmd);
    LCD_WR_DATA(yStar>>8);
    LCD_WR_DATA(0x00FF&yStar);
    LCD_WR_DATA(yEnd>>8);
    LCD_WR_DATA(0x00FF&yEnd);

    LCD_WriteRAM_Prepare();
}

